questionvariables.text:
/* 1. La vraie réponse mathématique */
ta1: rectform((3+2*%i)/(1-%i));

/* 2. Les erreurs typiques pour l'arbre de décision */
ta_oubli_div: 1 + 5*%i;
taErreurI2: 5/2 + 5/2*%i;

/* 3. L'affichage forcé de z avec texput pour empêcher la simplification d'affichage */
texput(z, "\\dfrac{3 + 2*i}{1 - i}");
